      SUBROUTINE DFBENDCC     CALCULATES DERIVATIVE OF FLOOR COORDINATE TRANSFORMATIONC     THROUGH A BENDING MAGNETCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'ELM28.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OIV.CIN'CC     LOCAL VARIABLESC      INTEGER  IANG, IB, IL, IRHO      REAL  ADOT, CSA2, DSAL, RDOT, RHO, RHODOT, SNA2, X1CC----------------------------------------------------------------      IL = IPTOJ(NL)      IB = IPTOJ(NBV)      IRHO = IPTOJ(NRHO)      IANG = IPTOJ(NANG)      IF (JV .EQ. NTILT) GO TO 200      IF (JV .GT. 4) GO TO 500      GO TO (10,20,30,40), JVC   10 IF (IB .NE. 0 .OR. IRHO .NE. 0) THEN        GO TO 100      ELSE IF (IANG .NE. 0) THEN        GO TO 110      ENDIF      GO TO 500C   20 IF (IL .NE. 0) THEN        RHO = 0.0        IF (H0 .NE. 0.0) RHO = 1.0/H0        RHODOT = - RHO**2*UNITI(9)/PREF        IF (TYPE .EQ. 4 .OR. TYPE .EQ. 29) THEN          ADOT = L*UNITI(9)/PREF        ELSE IF (TYPE .EQ. 28) THEN          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          ADOT = LRBEND*UNITI(9)/(PREF*CSA2)        ENDIF        GO TO 120      ELSE IF (IANG .NE. 0) THEN        GO TO 110      ENDIF      GO TO 500C   30 IF (IL .NE. 0) THEN        RHODOT = UNITI(8)        IF (TYPE .EQ. 4 .OR. TYPE .EQ. 29) THEN          ADOT = - H0**2*L*RHODOT        ELSE          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          ADOT = - H0**2*LRBEND*RHODOT/CSA2        ENDIF        GO TO 120      ELSE IF (IANG .NE. 0) THEN        GO TO 110      ENDIF      GO TO 500C   40 ADOT = UNITI(7)      IF (IL .NE. 0) THEN        IF (TYPE .EQ. 4 .OR. TYPE .EQ. 29) THEN          RHODOT = - L*UNITI(7)/AL**2        ELSE IF (TYPE .EQ. 28) THEN          SNA2 = 0.5*H0*LRBEND          CSA2 = SQRT(1.0 - SNA2**2)          IF (H0 .NE. 0.0) THEN            RHODOT = - CSA2*UNITI(7)/(H0**2*LRBEND)          ELSE            RHODOT = 0.0          ENDIF        ENDIF        GO TO 120      ELSE IF (IB .NE. 0 .OR. IRHO .NE. 0) THEN        RHODOT = 0.0        GO TO 130      ENDIF      GO TO 500C  100 OIV(1,1) = - SNAL*H0*LVE      OIV(3,3) = OIV(1,1)      OIV(1,3) = CSAL*H0*LVE      OIV(3,1) = - OIV(1,3)      XIV(1) = - SNAL*LVE      XIV(3) = CSAL*LVE      GO TO 500C  110 IF (H0 .EQ. 0.0) GO TO 115      IF (CSAL .LT. 0.5) THEN        DSAL = - (1.0 - CSAL)/H0      ELSE        DSAL = - SNAL**2/(H0*(1.0 + CSAL))      ENDIF      XIV(1) = DSAL*LVE/L      XIV(3) = SNAL*LVE/(H0*L)      GO TO 500C  115 WRITE (NOUT,9002) 9002 FORMAT (' ZERO BEND ANGLE NOT PERMITTED AS INITIAL VALUE',     1        ' FOR FITTING')      WRITE (NOUT,9003) LABEL(NUM) 9003 FORMAT (' ELEMENT IS ',A8)      FLUSHL = .TRUE.      GO TO 500C  120 OIV(1,1) = - SNAL*ADOT      OIV(3,3) = OIV(1,1)      OIV(1,3) = CSAL*ADOT      OIV(3,1) = - OIV(1,3)      IF (AL .NE. 0.0) THEN        XIV(1) = - (1.0 - CSAL)*RHODOT - SNAL*ADOT/H0        XIV(3) = SNAL*RHODOT + CSAL*ADOT/H0      ELSE        XIV(1) = - 0.5*L*ADOT        XIV(3) = - H0*L**2*ADOT/3.0      ENDIF      GO TO 500C  130 RHO = 0.0      IF (H0 .NE. 0.0) RHO = 1.0/H0      OIV(1,1) = - SNAL*ADOT      OIV(3,3) = OIV(1,1)      OIV(1,3) = CSAL*ADOT      OIV(3,1) = - OIV(1,3)      XIV(1) = - RHO*SNAL*ADOT      XIV(3) = RHO*SNAL*ADOT      GO TO 500C  200 IF (.NOT. REFER) GO TO 500      RDOT = UNITI(13)      OIV(1,1) = 2.0*(1.0 - CSAL)*SNR*CSR*RDOT      OIV(1,2) = (CSAL - 1.0)*(CSR**2 - SNR**2)*RDOT      OIV(1,3) = - SNAL*SNR*RDOT      OIV(2,1) = OIV(1,2)      OIV(2,2) = - 2.0*(1.0 - CSAL)*SNR*CSR*RDOT      OIV(2,3) = SNAL*CSR*RDOT      OIV(3,1) = - OIV(1,3)      OIV(3,2) = - OIV(2,3)      X1 = - (1.0 - CSAL)/H0      XIV(1) = - SNR*RDOT*X1      XIV(2) = CSR*RDOT*X1      GO TO 500C  500 RETURN      END